    },
    {
      "issue_id": "SPA-N-002",
      "position": "PARTIAL",
      "evidence": "assess whether the proposed thresholds are appropriate. Specify whether related claims aggregate and prevent artificial claim-splitting"
    },
    {
      "issue_id": "SPA-N-003",
      "position": "PARTIAL",
      "evidence": "The 18-month period should not be imposed on every claim by default."
    },
    {
      "issue_id": "SPA-N-004",
      "position": "PUSHBACK",
      "evidence": "Exclude title, capacity and authority claims from the general cap and ordinary thresholds"
    },
    {
      "issue_id": "SPA-N-005",
      "position": "PUSHBACK",
      "evidence": "Preserve uncapped or separately treated liability for fraud, fraudulent concealment and other agreed carve-outs."
    },
    {
      "issue_id": "SPA-N-006",
      "position": "PUSHBACK",
      "evidence": "Reject blanket data-room and public-register disclosure."
    },
    {
      "issue_id": "SPA-N-007",
      "position": "PUSHBACK",
      "evidence": "Reject the proposed Buyer-knowledge bar."
    },
    {
      "issue_id": "SPA-N-008",
      "position": "PUSHBACK",
      "evidence": "Require the consent and satisfaction or waiver of its conditions before completion, with termination rights if not obtained by a longstop date."
    },
    {
      "issue_id": "SPA-N-009",
      "position": "PUSHBACK",
      "evidence": "Require repayment from completion funds, lender payout and release documentation, and discharge of security as completion deliverables."
    },
    {
      "issue_id": "SPA-N-010",
      "position": "PUSHBACK",
      "evidence": "Require a complete completion funds flow and express allocation of the bonuses and on-costs."
    },
    {
      "issue_id": "SPA-N-011",
      "position": "PUSHBACK",
      "evidence": "a specific indemnity covering ownership, use, infringement and remediation."
    },
    {
      "issue_id": "SPA-N-012",
      "position": "PUSHBACK",
      "evidence": "Seek a specific indemnity or other tailored protection for losses arising from the incident"
    },
    {
      "issue_id": "SPA-N-013",
      "position": "PUSHBACK",
      "evidence": "Do not accept the Seller’s characterisation as ordinary operating costs without the contracts, renewal terms and liability analysis."
    },
    {
      "issue_id": "SPA-N-014",
      "position": "PUSHBACK",
      "evidence": "They should not cut across specific indemnities, price adjustments, completion obligations, equitable remedies, fraud carve-outs or any separately agreed claim regime."
    },
    {
      "issue_id": "SPA-N-015",
      "position": "PUSHBACK",
      "evidence": "that is evidence to check—not a substitute for title warranties and completion deliverables."
    },
    {
      "issue_id": "SPA-N-016",
      "position": "PUSHBACK",
      "evidence": "Give tax claims and specific indemnities their own appropriate caps and survival periods"
    }
  ],
